#!/usr/bin/env node
// License-tier gate removed 2026-04-23 — CC Commander is core free forever.
/**
 * intent-classifier.js
 * Hooks: UserPromptSubmit (route) + Stop ("what next")
 *
 * UserPromptSubmit — scores the prompt against hooks/lib/ccc-routes.json
 * (generated by scripts/build-routes.js) and injects a short <ccc-route>
 * block into the MODEL's context:
 *   high   → run the matching skill now, announcing it in one line
 *   medium → present the top candidates as a native menu (AskUserQuestion in
 *            Claude Code, request_user_input in Codex, numbered list elsewhere)
 *   low    → silent
 * Explicit /ccc-* or $ccc-* prompts and machine-generated turns are skipped.
 *
 * Stop — after a skill actually ran this turn, offers its next[] steps as a
 * menu (top-level decision:block + reason, which both hosts accept). At most
 * once per skill run and once per cooldown (a run inside it is dropped, not
 * deferred), never while stop_hook_active, never after the user picked
 * "Stop suggesting next steps" this session.
 * decision:block costs an extra model turn for each offered menu, including
 * chained skill runs and headless sessions. CCC_ROUTE_NEXT=off opts out.
 *
 * Fleet control-plane prompts (launch a lane, batch status, lane sweep, what's
 * running on the fleet) get a <ccc-fleet-route> block instead: the Fleet skill,
 * its read-only commands and the `ccc checkin` line (hooks/lib/fleet-intent.mjs).
 *
 * Env: CCC_ROUTE_MODE=off|suggest|auto (default auto; suggest never auto-runs;
 *        overrides the lane's saved `routeMode` in <config dir>/commander/config.json)
 *      CCC_FLEET_ROUTE=on|off Fleet routing (default: on only when the
 *        claude-fleet skill is installed)
 *      CCC_ROUTE_NEXT=off disables only the Stop menu
 *      CCC_ROUTE_NEXT_COOLDOWN_MIN minutes between Stop menus in a session
 *        (default 10; 0 offers after every skill run)
 *      CCC_ROUTE_MENU=list forces a numbered list instead of a native picker
 *
 * Telemetry is content-free: route id, score, tier, accepted. Prompts are
 * never logged or stored.
 */
import { track } from '../lib/telemetry.mjs';
import { emitUser, emitModel, emitBoth, emitSilent } from './lib/emit.mjs';
import {
  loadRoutes,
  scoreRoutes,
  skipReason,
  routeMode,
  tierFor,
  detectHost,
  renderRouteContext,
  renderNextContext,
  MUTE_NEXT_LABEL,
} from './lib/route-scorer.mjs';
import { fleetRouteEnabled, matchFleetIntent, fleetTools, checkinLine, renderFleetContext } from './lib/fleet-intent.mjs';
import { join } from 'node:path';
import { stateDir, readablePath } from '../lib/lane-state.js';
import { existsSync, writeFileSync, mkdirSync, readFileSync, appendFileSync, openSync, readSync, fstatSync, closeSync, renameSync, readdirSync, statSync, unlinkSync } from 'node:fs';

// Deep-reasoning signals for Fable escalation nudge
const FABLE_SIGNALS = [
  'architecture', 'redesign', 'migration', 'threat model', 'system design',
  'refactor entire', 'plan the', 'roadmap',
];
const FABLE_PLANNING_VERBS = ['design', 'architect', 'plan', 'migrate', 'refactor', 'model'];

function commanderDir() {
  return stateDir();
}

// The user's saved routing preference (/ccc-settings → config.json routeMode).
function savedRouteMode() {
  try {
    const config = JSON.parse(readFileSync(readablePath('config.json'), 'utf8'));
    return config && typeof config.routeMode === 'string' ? config.routeMode : null;
  } catch {
    return null;
  }
}

function checkFableNudge(prompt) {
  try {
    const lower = prompt.toLowerCase();
    const sigCount = FABLE_SIGNALS.filter(s => lower.includes(s)).length;
    const isLongWithVerbs = lower.length > 800 &&
      FABLE_PLANNING_VERBS.some(v => lower.includes(v));
    if (sigCount < 2 && !isLongWithVerbs) return null;

    // Check marker file (once per day keyed by date)
    const today = new Date().toISOString().slice(0, 10);
    const markerDir = commanderDir();
    const markerFile = join(markerDir, `fable-nudge-${today}`);
    if (existsSync(markerFile)) return null;

    // Write marker before returning so concurrent calls don't double-fire
    try { mkdirSync(markerDir, { recursive: true }); } catch (_) {}
    try { writeFileSync(markerFile, '', { flag: 'wx' }); } catch (_) { return null; }

    // Codex (PLUGIN_ROOT set) has no `fable` alias; its deep tier is GPT-6 Astra.
    return process.env.PLUGIN_ROOT
      ? '🧠 Deep-reasoning session detected — consider /model gpt-6-astra (GPT-6 Astra). CCC routes subagents cost-efficiently either way.'
      : '🧠 Deep-reasoning session detected — consider /model fable (Fable 5.1, 1M context). CCC routes subagents cost-efficiently either way.';
  } catch (_) {
    return null; // fail-safe: never break the hook
  }
}

// ── Per-session routing state (no prompt content) ─────────────────────────

function stateFile(sessionId) {
  const slug = String(sessionId || 'default').replace(/[^\w-]/g, '').slice(0, 80) || 'default';
  return join(commanderDir(), 'route-state', `${slug}.json`);
}

function loadState(sessionId) {
  try {
    return JSON.parse(readFileSync(stateFile(sessionId), 'utf8'));
  } catch {
    return {};
  }
}

function saveState(sessionId, state) {
  try {
    const file = stateFile(sessionId);
    mkdirSync(join(file, '..'), { recursive: true });
    // Write-then-rename: an overlapping hook never reads a truncated file.
    const tmp = `${file}.${process.pid}.tmp`;
    writeFileSync(tmp, JSON.stringify(state));
    renameSync(tmp, file);
  } catch {
    // state is best-effort
  }
}

const STATE_TTL_MS = 7 * 24 * 60 * 60 * 1000;

// Session state is only useful while a session is live; drop week-old files.
function pruneState() {
  try {
    const dir = join(commanderDir(), 'route-state');
    const cutoff = Date.now() - STATE_TTL_MS;
    for (const name of readdirSync(dir)) {
      const file = join(dir, name);
      if (statSync(file).mtimeMs < cutoff) unlinkSync(file);
    }
  } catch {
    // pruning is best-effort
  }
}

function logRouteEvent(entry) {
  try {
    const dir = commanderDir();
    mkdirSync(dir, { recursive: true });
    appendFileSync(join(dir, 'route-events.jsonl'), JSON.stringify({ ts: new Date().toISOString(), ...entry }) + '\n');
  } catch {
    // telemetry is best-effort
  }
  try {
    // Network delivery normally never starts in this short-lived hook: track
    // batches below ten events behind a 5s unref'd timer. This is lifecycle-
    // dependent, not a no-network guarantee; route-events.jsonl is local.
    track(`route_${entry.event}`, { route: entry.route, score: entry.score, tier: entry.tier, accepted: entry.accepted, host: entry.host });
  } catch {
    // telemetry must never block the hook chain
  }
}

// ── UserPromptSubmit ───────────────────────────────────────────────────────

const MUTE_PROMPT = /\b(stop|don'?t|do not|no more)\b.{0,20}\b(suggest|offer|ask)\w*\b.{0,20}\b(next steps?|what'?s next|what next)\b/i;

function handlePrompt(data) {
  const rawPrompt = String(data.prompt || data.message || '');
  if (!rawPrompt.trim()) return emitSilent();

  const fableNudge = checkFableNudge(rawPrompt);
  const host = detectHost();
  const mode = routeMode(process.env, savedRouteMode());
  let context = null;

  if (mode !== 'off' && !skipReason(rawPrompt, data)) {
    if (MUTE_PROMPT.test(rawPrompt)) {
      const state = loadState(data.session_id);
      saveState(data.session_id, { ...state, muteNext: true });
    } else if (matchFleetIntent(rawPrompt) && fleetRouteEnabled()) {
      // Fleet control-plane requests go to the Fleet skill, never dispatched from here.
      const intent = matchFleetIntent(rawPrompt);
      const tools = fleetTools();
      context = renderFleetContext(intent, tools, tools.cli || tools.skill ? checkinLine() : null, mode);
      logRouteEvent({ event: 'offered', route: `fleet:${intent.id}`, score: 1, tier: 'fleet', host, session_id: data.session_id || null });
    } else {
      const candidates = scoreRoutes(rawPrompt, loadRoutes());
      const tier = tierFor(candidates, mode);
      context = renderRouteContext(candidates, tier, host);
      if (context) {
        const top = candidates[0];
        const state = loadState(data.session_id);
        saveState(data.session_id, { ...state, offered: candidates.slice(0, 3).map((c) => c.route.id), offeredTier: tier });
        logRouteEvent({ event: 'offered', route: top.route.id, score: top.score, tier, host, session_id: data.session_id || null });
      }
    }
  }

  if (context && fableNudge) return emitBoth('UserPromptSubmit', fableNudge, context);
  if (context) return emitModel('UserPromptSubmit', context);
  if (fableNudge) return emitUser(fableNudge);
  return emitSilent();
}

// ── Stop: "what next" ──────────────────────────────────────────────────────

const TAIL_BYTES = 1024 * 1024;

function readTail(file) {
  let fd;
  try {
    fd = openSync(file, 'r');
    const size = fstatSync(fd).size;
    const length = Math.min(size, TAIL_BYTES);
    const buffer = Buffer.alloc(length);
    readSync(fd, buffer, 0, length, size - length);
    return buffer.toString('utf8');
  } catch {
    return '';
  } finally {
    if (fd !== undefined) try { closeSync(fd); } catch {}
  }
}

function skillIdFrom(name) {
  const id = String(name || '').replace(/^[/$]/, '').split(/\s/)[0].split(':').pop().toLowerCase();
  return /^[a-z][\w-]{0,60}$/.test(id) ? id : null;
}

function textOf(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.map((b) => (typeof b === 'string' ? b : b && (b.text || (typeof b.content === 'string' ? b.content : textOf(b.content))) || '')).join('\n');
}

/**
 * Scan the current turn of a Claude Code transcript: skills and agents that
 * ran, whether the user picked the mute option, and the last assistant text.
 */
function scanTurn(transcriptText) {
  const lines = transcriptText.split('\n').filter(Boolean);
  const turn = [];
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    let entry;
    try { entry = JSON.parse(lines[i]); } catch { continue; }
    turn.unshift(entry);
    const content = entry.message && entry.message.content;
    const isToolResult = Array.isArray(content) && content.some((b) => b && b.type === 'tool_result');
    if (entry.type === 'user' && !entry.isMeta && !isToolResult) break;
  }

  const ran = [];
  const askIds = new Set();
  let muted = false;
  let lastAssistantText = '';
  const claudeFormat = turn.some((e) => (e.type === 'user' || e.type === 'assistant') && e.message);
  for (const entry of turn) {
    const content = entry.message && entry.message.content;
    if (entry.type === 'user') {
      // Slash commands appear in the user's own text, never inside tool output.
      const plain = typeof content === 'string' ? content : Array.isArray(content) ? textOf(content.filter((b) => b && b.type === 'text')) : '';
      const cmd = plain.match(/<command-name>\s*([^<\s]+)\s*<\/command-name>/);
      if (cmd && skillIdFrom(cmd[1])) ran.push({ id: skillIdFrom(cmd[1]), key: entry.uuid || cmd[1] });
      // Mute only from the answer to an AskUserQuestion asked in this turn.
      if (Array.isArray(content) && content.some((b) => b && b.type === 'tool_result' && askIds.has(b.tool_use_id) && textOf([b]).includes(MUTE_NEXT_LABEL))) muted = true;
    }
    if (entry.type === 'assistant' && Array.isArray(content)) {
      for (const block of content) {
        if (block && block.type === 'tool_use' && block.name === 'AskUserQuestion') askIds.add(block.id);
        if (block && block.type === 'tool_use' && block.name === 'Skill') {
          const id = skillIdFrom(block.input && (block.input.skill || block.input.command));
          if (id) ran.push({ id, key: block.id || id });
        }
        if (block && block.type === 'tool_use' && (block.name === 'Agent' || block.name === 'Task')) {
          const id = skillIdFrom(block.input && block.input.subagent_type);
          if (id) ran.push({ id: `agent:${id}`, key: block.id || id });
        }
      }
      const text = textOf(content.filter((b) => b && b.type === 'text'));
      if (text.trim()) lastAssistantText = text.trim();
    }
  }
  return { ran, muted, lastAssistantText, claudeFormat };
}

// Codex (no Claude transcript format): fall back to skill-runs.jsonl, which
// skill-runs-logger.js writes for explicit $ccc-* / /ccc-* launches.
function recentSkillRuns(sessionId, sinceIso) {
  try {
    const text = readFileSync(join(commanderDir(), 'skill-runs.jsonl'), 'utf8').split('\n').slice(-200);
    const since = Date.parse(sinceIso || 0) || Date.now() - 2 * 60 * 60 * 1000;
    const runs = [];
    for (const line of text) {
      try {
        const run = JSON.parse(line);
        if (sessionId && run.session_id !== sessionId) continue;
        if (Date.parse(run.ts) > since && skillIdFrom(run.skill)) runs.push({ id: skillIdFrom(run.skill), key: run.ts });
      } catch {}
    }
    return runs;
  } catch {
    return [];
  }
}

const NEXT_COOLDOWN_MIN = 10;

function nextCooldownMs(env = process.env) {
  const raw = String(env.CCC_ROUTE_NEXT_COOLDOWN_MIN ?? '').trim();
  const minutes = raw === '' ? NaN : Number(raw);
  return (Number.isFinite(minutes) && minutes >= 0 ? minutes : NEXT_COOLDOWN_MIN) * 60 * 1000;
}

function coolingDown(lastOfferAt) {
  const elapsed = Date.now() - Date.parse(lastOfferAt);
  return elapsed >= 0 && elapsed < nextCooldownMs();
}

function handleStop(data) {
  if ((data.hook_event_name || 'Stop') !== 'Stop') return emitSilent();
  const sessionId = data.session_id;
  const state = loadState(sessionId);
  const turn = data.transcript_path ? scanTurn(readTail(data.transcript_path)) : { ran: [], muted: false, lastAssistantText: '', claudeFormat: false };
  // Claude Code transcripts are authoritative for this turn; the skill-runs
  // log is only for hosts whose transcript we cannot read (Codex).
  const ran = turn.claudeFormat ? turn.ran : recentSkillRuns(sessionId, state.lastNextAt);
  const next = { ...state };
  const host = detectHost();

  if (state.offered && state.offered.length) {
    const accepted = ran.find((r) => state.offered.includes(r.id));
    logRouteEvent({ event: 'outcome', route: accepted ? accepted.id : state.offered[0], tier: state.offeredTier, accepted: Boolean(accepted), host, session_id: sessionId || null });
    delete next.offered;
    delete next.offeredTier;
  }
  if (turn.muted) next.muteNext = true;

  let output = emitSilent();
  const enabled = routeMode(process.env, savedRouteMode()) !== 'off' && String(process.env.CCC_ROUTE_NEXT || '').toLowerCase() !== 'off';
  if (enabled && !data.stop_hook_active && !next.muteNext && ran.length) {
    const last = ran[ran.length - 1];
    const alreadyAsking = /\?\s*$/.test(turn.lastAssistantText);
    if (last.key !== state.lastNextKey && (alreadyAsking || coolingDown(state.lastOfferAt))) {
      // The skill ended on its own question, or a menu was offered recently:
      // consume this run without offering. Only an offer starts the cooldown.
      next.lastNextKey = last.key;
      next.lastNextAt = new Date().toISOString();
    } else if (last.key !== state.lastNextKey) {
      const routes = loadRoutes();
      const from = routes.find((r) => r.id === last.id);
      const options = from ? from.next.map((id) => routes.find((r) => r.id === id)).filter(Boolean) : [];
      const reason = renderNextContext(from, options, host);
      if (reason) {
        output = { ...emitSilent(), decision: 'block', reason };
        next.lastNextKey = last.key;
        next.lastNextAt = new Date().toISOString();
        next.lastOfferAt = next.lastNextAt;
        logRouteEvent({ event: 'next_offered', route: from.id, host, session_id: sessionId || null });
      }
    }
  }
  saveState(sessionId, next);
  pruneState();
  return output;
}

// ── main ───────────────────────────────────────────────────────────────────

async function main() {
  let event = 'UserPromptSubmit';
  try {
    // Read stdin first to avoid broken pipe on early exit
    let input = '';
    for await (const chunk of process.stdin) input += chunk;

    const data = JSON.parse(input);
    event = data.hook_event_name || (data.prompt !== undefined || data.message !== undefined ? 'UserPromptSubmit' : 'Stop');
    const out = event === 'UserPromptSubmit' ? handlePrompt(data) : handleStop(data);
    console.log(JSON.stringify(out));
  } catch {
    console.log(JSON.stringify({ continue: true, suppressOutput: true }));
  }

  track('hook_fired', { hook: event, handler: 'intent-classifier' });
}

main();
